    if (strcmp(iconId, "equipos/resistencia") == 0 || strcmp(iconId, "resistencia") == 0 || strcmp(iconId, "resistencia") == 0) return resistencia(size);
    if (strcmp(iconId, "equipos/agitador") == 0 || strcmp(iconId, "agitador") == 0 || strcmp(iconId, "agitador") == 0) return agitador(size);
    if (strcmp(iconId, "equipos/transportador") == 0 || strcmp(iconId, "transportador") == 0 || strcmp(iconId, "transportador") == 0) return transportador(size);
    if (strcmp(iconId, "sensores/proximidad") == 0 || strcmp(iconId, "proximidad") == 0 || strcmp(iconId, "proximidad") == 0) return proximidad(size);
    if (strcmp(iconId, "sensores/termometro") == 0 || strcmp(iconId, "termometro") == 0 || strcmp(iconId, "termometro") == 0) return termometro(size);
    if (strcmp(iconId, "sensores/manometro") == 0 || strcmp(iconId, "manometro") == 0 || strcmp(iconId, "manometro") == 0) return manometro(size);
    if (strcmp(iconId, "alarmas/alarma") == 0 || strcmp(iconId, "alarma") == 0 || strcmp(iconId, "alarma") == 0) return alarma(size);
    if (strcmp(iconId, "alarmas/campana") == 0 || strcmp(iconId, "campana") == 0 || strcmp(iconId, "campana") == 0) return campana(size);
    if (strcmp(iconId, "alarmas/sirena") == 0 || strcmp(iconId, "sirena") == 0 || strcmp(iconId, "sirena") == 0) return sirena(size);
    if (strcmp(iconId, "botones/pulsador") == 0 || strcmp(iconId, "pulsador") == 0 || strcmp(iconId, "pulsador") == 0) return pulsador(size);
    if (strcmp(iconId, "botones/paro_emergencia") == 0 || strcmp(iconId, "paro_emergencia") == 0 || strcmp(iconId, "paroEmergencia") == 0) return paroEmergencia(size);
    if (strcmp(iconId, "botones/selector") == 0 || strcmp(iconId, "selector") == 0 || strcmp(iconId, "selector") == 0) return selector(size);
    if (strcmp(iconId, "botones/contacto") == 0 || strcmp(iconId, "contacto") == 0 || strcmp(iconId, "contacto") == 0) return contacto(size);
    return motor(size); // fallback
